import '../models/models.dart';

class AnnualSecondaryFrenchUnit {
  final SchoolLevel level;
  final String code, title, lessonId, lessonTitle, summary, content;
  final int unitOrder;
  final List<String> keyPoints;
  final List<Exercise> exercises;
  const AnnualSecondaryFrenchUnit({
    required this.level, required this.code, required this.unitOrder,
    required this.title, required this.lessonId, required this.lessonTitle,
    required this.summary, required this.content, required this.keyPoints,
    required this.exercises,
  });
  String get subjectId => switch (code) {
    '6e' => 'fr',
    '5e' => 'cinq_fr',
    '4e' => 'quatre_fr',
    '3e' => 'trois_fr',
    _ => 'core_secondary_french_$code',
  };
  String get chapterId => 'core_secondary_french_${code}_unit_${unitOrder}';
}

const annualSecondaryFrenchUnits = <AnnualSecondaryFrenchUnit>[
  AnnualSecondaryFrenchUnit(level:SchoolLevel.cinquieme,code:'5e',unitOrder:1,title:'Les types et formes de phrases',lessonId:'core_fr_5e_sentence_types',lessonTitle:'Reconnaître les types et formes de phrases',summary:'Distinguer phrase déclarative, interrogative, impérative et exclamative.',content:'Une phrase commence par une majuscule et se termine par une ponctuation adaptée. La phrase déclarative donne une information et se termine souvent par un point. La phrase interrogative pose une question et se termine par un point d’interrogation. La phrase impérative exprime un ordre, un conseil ou une consigne. La phrase exclamative exprime une émotion. Une phrase peut être affirmative ou négative : « Il vient » / « Il ne vient pas ».',keyPoints:['Déclarative : information','Interrogative : question ?','Impérative : ordre ou conseil','Exclamative : émotion !','Négation : ne…pas'],exercises:[
    Exercise(id:'core_fr_5e_st1',lessonId:'core_fr_5e_sentence_types',question:'« Où vas-tu ? » est une phrase…',options:['Interrogative','Déclarative','Impérative'],correctIndex:0,explanation:'Elle pose une question et se termine par un point d’interrogation.'),
    Exercise(id:'core_fr_5e_st2',lessonId:'core_fr_5e_sentence_types',question:'Quelle phrase est à la forme négative ?',options:['Il ne parle pas.','Il parle.','Parle !'],correctIndex:0,explanation:'La négation est construite avec ne… pas.'),
    Exercise(id:'core_fr_5e_st3',lessonId:'core_fr_5e_sentence_types',question:'« Fermez vos cahiers. » est une phrase…',options:['Impérative','Interrogative','Exclamative'],correctIndex:0,explanation:'Elle donne une consigne.'),
  ]),
  AnnualSecondaryFrenchUnit(level:SchoolLevel.cinquieme,code:'5e',unitOrder:2,title:'Comprendre et résumer un récit',lessonId:'core_fr_5e_narrative',lessonTitle:'Identifier les étapes d’un récit',summary:'Repérer situation initiale, événement perturbateur, actions et dénouement.',content:'Un récit raconte des événements. On peut repérer la situation initiale (présentation des personnages et du cadre), l’événement perturbateur, les actions ou péripéties, le dénouement et la situation finale. Pour résumer, conserve les idées principales dans l’ordre, utilise tes propres mots et évite les détails secondaires ou les dialogues inutiles.',keyPoints:['Repérer les étapes du récit','Respecter l’ordre chronologique','Résumer avec les idées essentielles'],exercises:[
    Exercise(id:'core_fr_5e_na1',lessonId:'core_fr_5e_narrative',question:'Quelle partie présente les personnages et le cadre ?',options:['Situation initiale','Dénouement','Péripétie finale'],correctIndex:0,explanation:'La situation initiale présente le cadre et les personnages.'),
    Exercise(id:'core_fr_5e_na2',lessonId:'core_fr_5e_narrative',question:'Un bon résumé doit…',options:['Garder les idées principales','Copier tous les dialogues','Ajouter des événements inventés'],correctIndex:0,explanation:'Le résumé reprend l’essentiel sans inventer.'),
    Exercise(id:'core_fr_5e_na3',lessonId:'core_fr_5e_narrative',question:'L’événement qui lance l’action est…',options:['L’événement perturbateur','La situation finale','La description du titre'],correctIndex:0,explanation:'L’événement perturbateur déclenche les actions du récit.'),
  ]),
  AnnualSecondaryFrenchUnit(level:SchoolLevel.quatrieme,code:'4e',unitOrder:1,title:'La phrase complexe',lessonId:'core_fr_4e_complex_sentence',lessonTitle:'Construire une phrase complexe',summary:'Distinguer propositions et utiliser coordination ou subordination.',content:'Une phrase simple contient un seul verbe conjugué. Une phrase complexe contient plusieurs propositions, généralement repérées par plusieurs verbes conjugués. Les propositions peuvent être juxtaposées (ponctuation), coordonnées (mais, ou, et, donc, or, ni, car) ou subordonnées (introduites par un mot subordonnant). Choisis le lien logique qui exprime la relation entre les idées : cause, conséquence, opposition, condition ou temps.',keyPoints:['Compter les verbes conjugués','Juxtaposition : ponctuation','Coordination : conjonction','Subordination : proposition dépendante'],exercises:[
    Exercise(id:'core_fr_4e_cs1',lessonId:'core_fr_4e_complex_sentence',question:'Dans « Il pleut, nous restons à la maison », les propositions sont…',options:['Juxtaposées','Subordonnées','Sans lien'],correctIndex:0,explanation:'Elles sont séparées par une virgule sans conjonction.'),
    Exercise(id:'core_fr_4e_cs2',lessonId:'core_fr_4e_complex_sentence',question:'Quel mot exprime généralement la cause ?',options:['Parce que','Pourtant','Puis'],correctIndex:0,explanation:'« Parce que » introduit une cause.'),
    Exercise(id:'core_fr_4e_cs3',lessonId:'core_fr_4e_complex_sentence',question:'Combien de propositions dans « Afi lit et Kossi écrit » ?',options:['Deux','Une','Trois'],correctIndex:0,explanation:'Il y a deux verbes conjugués : lit et écrit.'),
  ]),
  AnnualSecondaryFrenchUnit(level:SchoolLevel.quatrieme,code:'4e',unitOrder:2,title:'Le texte argumentatif',lessonId:'core_fr_4e_argument',lessonTitle:'Défendre une opinion avec des arguments',summary:'Formuler une thèse, donner des arguments et les illustrer par des exemples.',content:'Un texte argumentatif cherche à convaincre ou persuader. La thèse est l’opinion défendue. Les arguments expliquent pourquoi cette opinion est soutenue ; les exemples rendent les arguments concrets. Organise le texte avec une introduction, des paragraphes reliés par des connecteurs logiques et une conclusion. Distingue un fait vérifiable d’une opinion personnelle.',keyPoints:['Thèse : opinion défendue','Argument : raison qui soutient la thèse','Exemple : illustration concrète','Connecteurs : d’abord, ensuite, enfin, cependant'],exercises:[
    Exercise(id:'core_fr_4e_ar1',lessonId:'core_fr_4e_argument',question:'Dans un texte argumentatif, la thèse est…',options:['L’opinion défendue','Un exemple seulement','Le titre obligatoire'],correctIndex:0,explanation:'La thèse exprime l’opinion que l’auteur cherche à défendre.'),
    Exercise(id:'core_fr_4e_ar2',lessonId:'core_fr_4e_argument',question:'À quoi sert un exemple ?',options:['À illustrer un argument','À remplacer tous les arguments','À supprimer la conclusion'],correctIndex:0,explanation:'Un exemple rend l’argument plus concret.'),
    Exercise(id:'core_fr_4e_ar3',lessonId:'core_fr_4e_argument',question:'Quel connecteur marque l’opposition ?',options:['Cependant','Donc','D’abord'],correctIndex:0,explanation:'« Cependant » introduit une opposition ou une nuance.'),
  ]),
  AnnualSecondaryFrenchUnit(level:SchoolLevel.troisieme,code:'3e',unitOrder:1,title:'Analyser un texte littéraire',lessonId:'core_fr_3e_literary_analysis',lessonTitle:'Lire, interpréter et justifier une réponse',summary:'Identifier le genre, le thème, le point de vue et appuyer une interprétation par le texte.',content:'Pour analyser un texte, commence par identifier son genre (récit, poésie, théâtre, argumentation), son thème et la situation d’énonciation. Repère les procédés d’écriture : comparaison, métaphore, répétition, champ lexical, rythme ou dialogue. Une interprétation doit être justifiée par une citation courte ou un élément précis du texte. Explique ensuite l’effet produit sur le lecteur.',keyPoints:['Identifier genre et thème','Repérer les procédés d’écriture','Justifier avec un indice du texte','Expliquer l’effet produit'],exercises:[
    Exercise(id:'core_fr_3e_la1',lessonId:'core_fr_3e_literary_analysis',question:'Pour justifier une interprétation, il faut…',options:['Citer un indice précis du texte','Inventer une citation','Donner seulement son avis'],correctIndex:0,explanation:'Une interprétation s’appuie sur des éléments observables du texte.'),
    Exercise(id:'core_fr_3e_la2',lessonId:'core_fr_3e_literary_analysis',question:'« Il est fort comme un lion » contient…',options:['Une comparaison','Une métaphore sans outil','Une hyperbole numérique'],correctIndex:0,explanation:'Le mot « comme » introduit une comparaison.'),
    Exercise(id:'core_fr_3e_la3',lessonId:'core_fr_3e_literary_analysis',question:'Le champ lexical regroupe…',options:['Des mots liés à un même thème','Tous les verbes du texte','Uniquement les noms propres'],correctIndex:0,explanation:'Un champ lexical rassemble des mots associés à une idée ou un thème.'),
  ]),
  AnnualSecondaryFrenchUnit(level:SchoolLevel.troisieme,code:'3e',unitOrder:2,title:'Rédiger un paragraphe argumenté',lessonId:'core_fr_3e_writing',lessonTitle:'Organiser une argumentation claire',summary:'Rédiger un paragraphe avec une idée, un argument, un exemple et une conclusion.',content:'Un paragraphe argumenté répond clairement à une question. Commence par une idée directrice, développe un argument, donne un exemple précis et termine par une phrase qui relie l’exemple à l’idée. Utilise des connecteurs logiques et relis la grammaire, les accords, la ponctuation et l’orthographe. Évite les répétitions en utilisant des synonymes ou des pronoms adaptés.',keyPoints:['Une idée directrice claire','Argument + exemple','Connecteurs logiques','Relire accords et ponctuation'],exercises:[
    Exercise(id:'core_fr_3e_wr1',lessonId:'core_fr_3e_writing',question:'Quel ordre convient à un paragraphe argumenté ?',options:['Idée, argument, exemple, conclusion','Exemple, titre, mots au hasard','Conclusion uniquement'],correctIndex:0,explanation:'L’organisation logique aide le lecteur à suivre le raisonnement.'),
    Exercise(id:'core_fr_3e_wr2',lessonId:'core_fr_3e_writing',question:'Quel connecteur introduit un exemple ?',options:['Par exemple','En revanche','Donc'],correctIndex:0,explanation:'« Par exemple » annonce une illustration.'),
    Exercise(id:'core_fr_3e_wr3',lessonId:'core_fr_3e_writing',question:'Que faut-il vérifier à la relecture ?',options:['Accords, ponctuation et orthographe','Seulement la longueur','La couleur du papier'],correctIndex:0,explanation:'La relecture vérifie la correction et la clarté du texte.'),
  ]),
  AnnualSecondaryFrenchUnit(level:SchoolLevel.cinquieme,code:'5e',unitOrder:3,title:'Le groupe nominal et ses expansions',lessonId:'core_fr_5e_noun_group',lessonTitle:'Enrichir un groupe nominal',summary:'Identifier le nom noyau, le déterminant, l’adjectif et le complément du nom.',content:'Le groupe nominal est organisé autour d’un nom noyau. Il peut comporter un déterminant, un ou plusieurs adjectifs et un complément du nom. Exemple : « les grands arbres de la cour » : arbres est le nom noyau, les est le déterminant, grands est l’adjectif et de la cour est le complément du nom. Les expansions précisent le nom.',keyPoints:['Le nom est le noyau du groupe nominal','L’adjectif précise le nom','Le complément du nom est souvent introduit par une préposition'],exercises:[
    Exercise(id:'core_fr_5e_ng1',lessonId:'core_fr_5e_noun_group',question:'Dans « une belle maison », quel mot est le nom noyau ?',options:['belle','maison','une'],correctIndex:1,explanation:'Maison est le nom ; belle est un adjectif qualificatif.'),
    Exercise(id:'core_fr_5e_ng2',lessonId:'core_fr_5e_noun_group',question:'Dans « le cahier de Kossi », « de Kossi » est…',options:['Un complément du nom','Un verbe','Un déterminant'],correctIndex:0,explanation:'Le groupe introduit par de précise le nom cahier.'),
    Exercise(id:'core_fr_5e_ng3',lessonId:'core_fr_5e_noun_group',question:'Quel mot est un adjectif dans « une robe rouge » ?',options:['une','robe','rouge'],correctIndex:2,explanation:'Rouge donne une précision sur le nom robe.'),
  ]),
  AnnualSecondaryFrenchUnit(level:SchoolLevel.cinquieme,code:'5e',unitOrder:4,title:'Conjugaison au présent et à l’imparfait',lessonId:'core_fr_5e_present_imperfect',lessonTitle:'Conjuguer les verbes dans un récit',summary:'Employer le présent et l’imparfait et reconnaître leurs valeurs usuelles.',content:'Le présent peut exprimer une action actuelle, une habitude ou une vérité générale. À l’imparfait, les terminaisons sont -ais, -ais, -ait, -ions, -iez, -aient. On forme généralement l’imparfait à partir de nous au présent, en retirant -ons et en ajoutant les terminaisons. Dans un récit, l’imparfait sert souvent à décrire ou à présenter une habitude passée.',keyPoints:['Présent : action actuelle, habitude ou vérité','Imparfait : -ais, -ais, -ait, -ions, -iez, -aient','Imparfait souvent utilisé pour la description passée'],exercises:[
    Exercise(id:'core_fr_5e_pi1',lessonId:'core_fr_5e_present_imperfect',question:'À l’imparfait, « nous chantons » devient…',options:['nous chantions','nous chanterons','nous avons chanté'],correctIndex:0,explanation:'On retire -ons de chantons et on ajoute -ions.'),
    Exercise(id:'core_fr_5e_pi2',lessonId:'core_fr_5e_present_imperfect',question:'Dans « Chaque soir, il lisait », l’imparfait exprime…',options:['Une habitude passée','Un ordre','Une action future'],correctIndex:0,explanation:'Chaque soir indique une action répétée dans le passé.'),
    Exercise(id:'core_fr_5e_pi3',lessonId:'core_fr_5e_present_imperfect',question:'Quelle terminaison correspond à « ils » à l’imparfait ?',options:['-aient','-ions','-iez'],correctIndex:0,explanation:'La terminaison de la 3e personne du pluriel est -aient.'),
  ]),
  AnnualSecondaryFrenchUnit(level:SchoolLevel.cinquieme,code:'5e',unitOrder:5,title:'Accord du verbe avec le sujet',lessonId:'core_fr_5e_subject_verb_agreement',lessonTitle:'Accorder correctement le verbe',summary:'Repérer le sujet et accorder le verbe même lorsque le sujet est éloigné.',content:'Le verbe conjugué s’accorde en personne et en nombre avec son sujet. Pour trouver le sujet, pose la question « qui est-ce qui ? » ou « qu’est-ce qui ? » devant le verbe. Le sujet peut être un groupe nominal ou un pronom. Même si des mots séparent le sujet du verbe, l’accord reste commandé par le sujet : Les élèves de cette classe travaillent.',keyPoints:['Identifier le sujet du verbe','Accorder en personne et en nombre','Ne pas confondre le sujet avec un nom proche'],exercises:[
    Exercise(id:'core_fr_5e_sv1',lessonId:'core_fr_5e_subject_verb_agreement',question:'Les enfants ___ dans la cour.',options:['joue','jouent','joues'],correctIndex:1,explanation:'Le sujet les enfants est au pluriel : jouent.'),
    Exercise(id:'core_fr_5e_sv2',lessonId:'core_fr_5e_subject_verb_agreement',question:'La fille et son frère ___ tôt.',options:['arrive','arrivent','arrives'],correctIndex:1,explanation:'Le sujet composé est pluriel : arrivent.'),
    Exercise(id:'core_fr_5e_sv3',lessonId:'core_fr_5e_subject_verb_agreement',question:'Dans « Le panier de mangues tombe », le sujet est…',options:['de mangues','le panier','mangues'],correctIndex:1,explanation:'Le noyau du sujet est panier, au singulier : tombe.'),
  ]),
  AnnualSecondaryFrenchUnit(level:SchoolLevel.cinquieme,code:'5e',unitOrder:6,title:'Décrire une personne et écrire une lettre',lessonId:'core_fr_5e_description_letter',lessonTitle:'Organiser une description et une lettre simple',summary:'Utiliser un vocabulaire précis et respecter la structure d’une lettre personnelle.',content:'Une description présente les traits importants d’une personne ou d’un lieu dans un ordre logique. Choisis des adjectifs précis et évite les répétitions. Une lettre personnelle comporte généralement le lieu et la date, une formule d’appel, le message organisé en paragraphes, une formule de clôture et la signature. Adapte le ton au destinataire.',keyPoints:['Organiser la description du général au particulier','Varier les adjectifs et éviter les répétitions','Respecter les parties d’une lettre'],exercises:[
    Exercise(id:'core_fr_5e_dl1',lessonId:'core_fr_5e_description_letter',question:'Quel élément ouvre généralement une lettre personnelle ?',options:['Une formule d’appel','La signature','La formule de clôture'],correctIndex:0,explanation:'La lettre commence par une formule d’appel comme « Cher… ».'),
    Exercise(id:'core_fr_5e_dl2',lessonId:'core_fr_5e_description_letter',question:'Pour éviter les répétitions dans une description, on peut…',options:['Utiliser des mots précis et des synonymes','Répéter le même adjectif','Supprimer toutes les informations'],correctIndex:0,explanation:'Le vocabulaire varié rend la description plus précise.'),
    Exercise(id:'core_fr_5e_dl3',lessonId:'core_fr_5e_description_letter',question:'Où place-t-on généralement la signature ?',options:['À la fin de la lettre','Avant le message','Dans la formule d’appel'],correctIndex:0,explanation:'La signature se place à la fin du message et de la formule de clôture.'),
  ]),
  AnnualSecondaryFrenchUnit(level:SchoolLevel.quatrieme,code:'4e',unitOrder:3,title:'Les pronoms et la proposition relative',lessonId:'core_fr_4e_relative_pronouns',lessonTitle:'Enrichir une phrase avec une relative',summary:'Employer qui, que, dont et où pour relier des informations.',content:'Une proposition subordonnée relative complète un nom appelé antécédent. Elle est introduite par un pronom relatif. Qui est généralement sujet : « l’élève qui répond ». Que est généralement complément d’objet direct : « le livre que je lis ». Où indique souvent un lieu ou un moment. Dont remplace un complément introduit par de : « l’ami dont je parle ».',keyPoints:['Qui : sujet de la relative','Que : souvent COD','Où : lieu ou temps ; dont : complément en de'],exercises:[
    Exercise(id:'core_fr_4e_rp1',lessonId:'core_fr_4e_relative_pronouns',question:'« La fille ___ chante est ma sœur. »',options:['qui','que','dont'],correctIndex:0,explanation:'Qui est sujet du verbe chante.'),
    Exercise(id:'core_fr_4e_rp2',lessonId:'core_fr_4e_relative_pronouns',question:'« Le film ___ nous regardons est intéressant. »',options:['que','qui','où'],correctIndex:0,explanation:'Que remplace le COD du verbe regardons.'),
    Exercise(id:'core_fr_4e_rp3',lessonId:'core_fr_4e_relative_pronouns',question:'« La ville ___ je suis né… »',options:['où','que','dont'],correctIndex:0,explanation:'Où indique le lieu.'),
  ]),
  AnnualSecondaryFrenchUnit(level:SchoolLevel.quatrieme,code:'4e',unitOrder:4,title:'Organiser un récit et son point de vue',lessonId:'core_fr_4e_narrative_point',lessonTitle:'Construire un récit cohérent',summary:'Repérer le narrateur, le point de vue et les étapes d’un récit.',content:'Le narrateur raconte l’histoire ; il ne doit pas être confondu avec l’auteur. À la première personne, le narrateur dit je. À la troisième personne, il raconte en utilisant il ou elle. Le point de vue peut être interne (on connaît les pensées d’un personnage), externe (on décrit ce qui est observable) ou omniscient (le narrateur sait tout). Un récit s’organise en étapes et utilise des connecteurs temporels.',keyPoints:['Auteur et narrateur sont différents','Point de vue interne, externe ou omniscient','Connecteurs : d’abord, ensuite, enfin'],exercises:[
    Exercise(id:'core_fr_4e_np1',lessonId:'core_fr_4e_narrative_point',question:'Le narrateur est…',options:['La voix qui raconte l’histoire','Toujours l’auteur réel','Le lecteur'],correctIndex:0,explanation:'Le narrateur est l’instance qui raconte le récit.'),
    Exercise(id:'core_fr_4e_np2',lessonId:'core_fr_4e_narrative_point',question:'Le point de vue interne donne accès…',options:['Aux pensées d’un personnage','À aucune information','Uniquement à la météo'],correctIndex:0,explanation:'Le lecteur découvre les événements à travers la perception d’un personnage.'),
    Exercise(id:'core_fr_4e_np3',lessonId:'core_fr_4e_narrative_point',question:'Quel connecteur marque la fin d’une suite ?',options:['Enfin','D’abord','Pendant que'],correctIndex:0,explanation:'Enfin peut annoncer la dernière étape.'),
  ]),
  AnnualSecondaryFrenchUnit(level:SchoolLevel.quatrieme,code:'4e',unitOrder:5,title:'Accord du participe passé',lessonId:'core_fr_4e_past_participle',lessonTitle:'Accorder le participe passé dans les cas courants',summary:'Appliquer les règles de base avec être et avoir.',content:'Avec l’auxiliaire être, le participe passé s’accorde généralement avec le sujet : elles sont parties. Avec avoir, il ne s’accorde généralement pas avec le sujet : ils ont mangé. Dans la règle scolaire usuelle, avec avoir, le participe passé peut s’accorder avec le COD placé avant le verbe : les lettres qu’elle a écrites. Il faut repérer l’auxiliaire et le COD.',keyPoints:['Avec être : accord avec le sujet','Avec avoir : pas d’accord avec le sujet','Avec avoir : COD placé avant peut commander l’accord'],exercises:[
    Exercise(id:'core_fr_4e_pp1',lessonId:'core_fr_4e_past_participle',question:'Les filles sont ___ tôt.',options:['parties','parti','partis'],correctIndex:0,explanation:'Avec être, le participe passé s’accorde avec le sujet féminin pluriel.'),
    Exercise(id:'core_fr_4e_pp2',lessonId:'core_fr_4e_past_participle',question:'Ils ont ___ le repas.',options:['préparé','préparés','préparées'],correctIndex:0,explanation:'Avec avoir, le COD le repas est placé après : pas d’accord.'),
    Exercise(id:'core_fr_4e_pp3',lessonId:'core_fr_4e_past_participle',question:'Les chansons qu’elle a ___ sont belles.',options:['chantées','chanté','chantés'],correctIndex:0,explanation:'Le COD les chansons est placé avant et commande l’accord au féminin pluriel.'),
  ]),
  AnnualSecondaryFrenchUnit(level:SchoolLevel.quatrieme,code:'4e',unitOrder:6,title:'Écrire une lettre argumentative',lessonId:'core_fr_4e_argument_letter',lessonTitle:'Défendre une opinion dans une lettre',summary:'Présenter une thèse, des arguments, des exemples et une conclusion.',content:'Une lettre argumentative présente clairement une opinion. Chaque argument doit soutenir cette opinion et peut être accompagné d’un exemple. Utilise des connecteurs comme d’abord, ensuite, en effet, par exemple, cependant et donc. Respecte les codes de la lettre : destinataire, formule d’appel, paragraphes, formule de clôture et signature.',keyPoints:['Opinion ou thèse clairement formulée','Arguments accompagnés d’exemples','Connecteurs logiques et structure de lettre'],exercises:[
    Exercise(id:'core_fr_4e_al1',lessonId:'core_fr_4e_argument_letter',question:'Un argument sert à…',options:['Justifier une opinion','Changer de sujet sans raison','Remplacer la conclusion'],correctIndex:0,explanation:'Un argument apporte une raison qui soutient la thèse.'),
    Exercise(id:'core_fr_4e_al2',lessonId:'core_fr_4e_argument_letter',question:'Quel connecteur introduit une opposition ?',options:['Cependant','Donc','Par exemple'],correctIndex:0,explanation:'Cependant marque une opposition ou une réserve.'),
    Exercise(id:'core_fr_4e_al3',lessonId:'core_fr_4e_argument_letter',question:'Un exemple sert à…',options:['Illustrer un argument','Supprimer l’opinion','Remplacer le destinataire'],correctIndex:0,explanation:'L’exemple rend l’argument concret et compréhensible.'),
  ]),
  AnnualSecondaryFrenchUnit(level:SchoolLevel.troisieme,code:'3e',unitOrder:3,title:'Discours direct et discours indirect',lessonId:'core_fr_3e_reported_speech',lessonTitle:'Rapporter les paroles d’un personnage',summary:'Distinguer les paroles citées et les paroles rapportées.',content:'Au discours direct, les paroles sont reproduites telles qu’elles sont prononcées, souvent avec des guillemets ou des tirets. Au discours indirect, elles sont intégrées dans une phrase avec un verbe de parole et une subordonnée : Il dit : « Je viens » devient Il dit qu’il vient. Selon le temps du verbe introducteur, les pronoms, les temps et les repères de lieu ou de temps peuvent changer.',keyPoints:['Direct : paroles citées','Indirect : paroles intégrées avec que/si ou un mot interrogatif','Adapter pronoms et repères selon le contexte'],exercises:[
    Exercise(id:'core_fr_3e_rs1',lessonId:'core_fr_3e_reported_speech',question:'Au discours direct, les paroles sont…',options:['Reproduites telles qu’elles sont prononcées','Toujours résumées','Supprimées'],correctIndex:0,explanation:'Le discours direct cite les paroles du personnage.'),
    Exercise(id:'core_fr_3e_rs2',lessonId:'core_fr_3e_reported_speech',question:'« Il dit : Je suis prêt. » au discours indirect devient…',options:['Il dit qu’il est prêt.','Il dit je prêt.','Il dit qu’il était prêt hier dans tous les cas.'],correctIndex:0,explanation:'Le pronom je devient il et la phrase est introduite par que.'),
    Exercise(id:'core_fr_3e_rs3',lessonId:'core_fr_3e_reported_speech',question:'Quel élément introduit souvent une déclaration au discours indirect ?',options:['que','mais uniquement','car toujours'],correctIndex:0,explanation:'Une déclaration est souvent introduite par que.'),
  ]),
  AnnualSecondaryFrenchUnit(level:SchoolLevel.troisieme,code:'3e',unitOrder:4,title:'Voix active et voix passive',lessonId:'core_fr_3e_active_passive',lessonTitle:'Transformer une phrase active en passive',summary:'Identifier l’agent, le sujet et le complément dans les deux voix.',content:'À la voix active, le sujet fait l’action : Le professeur corrige la copie. À la voix passive, le sujet subit l’action : La copie est corrigée par le professeur. La forme passive se construit avec être au temps voulu + participe passé, qui s’accorde avec le sujet. Le complément d’agent est souvent introduit par par ou de.',keyPoints:['Active : sujet agent de l’action','Passive : être + participe passé','Le participe passé s’accorde avec le sujet passif'],exercises:[
    Exercise(id:'core_fr_3e_ap1',lessonId:'core_fr_3e_active_passive',question:'« Le jardinier arrose les plantes. » à la voix passive…',options:['Les plantes sont arrosées par le jardinier.','Le jardinier est arrosé.','Les plantes arrose le jardinier.'],correctIndex:0,explanation:'Le COD les plantes devient sujet ; être + participe passé est utilisé.'),
    Exercise(id:'core_fr_3e_ap2',lessonId:'core_fr_3e_active_passive',question:'La voix passive se forme avec…',options:['être + participe passé','avoir + infinitif toujours','un adjectif seulement'],correctIndex:0,explanation:'La construction passive utilise l’auxiliaire être et le participe passé.'),
    Exercise(id:'core_fr_3e_ap3',lessonId:'core_fr_3e_active_passive',question:'Dans la phrase passive, le complément d’agent indique…',options:['Qui réalise l’action','Le lieu seulement','Le temps du récit'],correctIndex:0,explanation:'Le complément d’agent désigne l’auteur de l’action.'),
  ]),
  AnnualSecondaryFrenchUnit(level:SchoolLevel.troisieme,code:'3e',unitOrder:5,title:'La phrase complexe et les connecteurs',lessonId:'core_fr_3e_complex_connectors',lessonTitle:'Relier les idées dans un texte',summary:'Identifier les propositions et choisir des connecteurs logiques.',content:'Une phrase complexe contient plusieurs propositions. Les propositions peuvent être juxtaposées, coordonnées ou subordonnées. Les connecteurs expriment les relations entre les idées : cause (parce que), conséquence (donc), opposition (mais, cependant), concession (bien que) ou but (pour que). Choisis un connecteur qui correspond au sens et vérifie la construction grammaticale.',keyPoints:['Juxtaposition, coordination, subordination','Cause : parce que ; conséquence : donc','Opposition : mais/cependant ; but : pour que'],exercises:[
    Exercise(id:'core_fr_3e_cc1',lessonId:'core_fr_3e_complex_connectors',question:'Quel connecteur exprime la conséquence ?',options:['Donc','Parce que','Bien que'],correctIndex:0,explanation:'Donc introduit une conséquence.'),
    Exercise(id:'core_fr_3e_cc2',lessonId:'core_fr_3e_complex_connectors',question:'« Il est venu ___ il était malade. » (opposition)',options:['mais','donc','parce que'],correctIndex:0,explanation:'Mais exprime l’opposition entre les deux idées.'),
    Exercise(id:'core_fr_3e_cc3',lessonId:'core_fr_3e_complex_connectors',question:'Une phrase complexe contient…',options:['Plusieurs propositions','Toujours un seul mot','Aucun verbe'],correctIndex:0,explanation:'Une phrase complexe contient plusieurs propositions.'),
  ]),
  AnnualSecondaryFrenchUnit(level:SchoolLevel.troisieme,code:'3e',unitOrder:6,title:'Méthode de rédaction et relecture',lessonId:'core_fr_3e_writing_method',lessonTitle:'Construire une réponse écrite organisée',summary:'Préparer, rédiger et relire un texte en respectant la consigne.',content:'Avant de rédiger, repère le sujet, le type de texte, le destinataire et les contraintes. Prépare un plan simple : introduction ou idée principale, développement en paragraphes, conclusion. Chaque paragraphe doit traiter une idée et utiliser des exemples ou des arguments adaptés. Relis ensuite les accords, les temps, la ponctuation et l’orthographe.',keyPoints:['Analyser la consigne et le destinataire','Organiser les idées en paragraphes','Relire le fond et la langue'],exercises:[
    Exercise(id:'core_fr_3e_wm1',lessonId:'core_fr_3e_writing_method',question:'Avant de rédiger, il faut d’abord…',options:['Analyser la consigne','Écrire sans lire le sujet','Copier un texte au hasard'],correctIndex:0,explanation:'L’analyse de la consigne permet de répondre au sujet demandé.'),
    Exercise(id:'core_fr_3e_wm2',lessonId:'core_fr_3e_writing_method',question:'Un paragraphe bien organisé développe…',options:['Une idée principale','Toutes les idées sans ordre','Seulement le titre'],correctIndex:0,explanation:'Chaque paragraphe doit développer une idée cohérente.'),
    Exercise(id:'core_fr_3e_wm3',lessonId:'core_fr_3e_writing_method',question:'La relecture doit vérifier…',options:['Accords, ponctuation et sens','Uniquement le nombre de lignes','La couleur de l’encre'],correctIndex:0,explanation:'La relecture vérifie la clarté et la correction du texte.'),
  ]),
  AnnualSecondaryFrenchUnit(level:SchoolLevel.sixieme,code:'6e',unitOrder:1,title:'Classes grammaticales',lessonId:'core_fr_6e_word_classes',lessonTitle:'Reconnaître les principales classes de mots',summary:'Distinguer nom, déterminant, adjectif, pronom, verbe et adverbe.',content:'La classe grammaticale indique la nature d’un mot. Le nom désigne une personne, un animal, une chose ou une idée. Le déterminant accompagne le nom ; l’adjectif le précise. Le verbe exprime une action ou un état. Le pronom remplace un nom ou un groupe nominal. L’adverbe précise souvent un verbe, un adjectif ou un autre adverbe. La classe d’un mot ne change pas selon sa fonction dans la phrase.',keyPoints:['Nature = classe grammaticale','Nom, déterminant, adjectif, verbe, pronom, adverbe','La fonction est différente de la nature'],exercises:[
    Exercise(id:'core_fr_6e_wc1',lessonId:'core_fr_6e_word_classes',question:'Dans « les grands arbres », « grands » est…',options:['Un adjectif','Un verbe','Un pronom'],correctIndex:0,explanation:'Grands précise le nom arbres : c’est un adjectif.'),
    Exercise(id:'core_fr_6e_wc2',lessonId:'core_fr_6e_word_classes',question:'Quel mot est un verbe ?',options:['courir','maison','beau'],correctIndex:0,explanation:'Courir exprime une action et est un verbe à l’infinitif.'),
    Exercise(id:'core_fr_6e_wc3',lessonId:'core_fr_6e_word_classes',question:'Dans « elle chante », « elle » est…',options:['Un pronom','Un adjectif','Un déterminant'],correctIndex:0,explanation:'Elle remplace un nom ou désigne une personne : c’est un pronom.'),
  ]),
  AnnualSecondaryFrenchUnit(level:SchoolLevel.sixieme,code:'6e',unitOrder:2,title:'Conjugaison au présent et au passé composé',lessonId:'core_fr_6e_tenses',lessonTitle:'Conjuguer des verbes usuels',summary:'Employer le présent et former le passé composé avec avoir ou être.',content:'Le présent exprime une action actuelle, une habitude ou une vérité. Le passé composé exprime souvent une action achevée. Il se forme avec avoir ou être au présent suivi du participe passé : j’ai joué, elle est arrivée. Avec être, le participe passé s’accorde généralement avec le sujet. Apprends les formes fréquentes des verbes être, avoir, aller, faire et venir.',keyPoints:['Présent : action actuelle ou habitude','Passé composé : avoir/être + participe passé','Avec être, accord avec le sujet'],exercises:[
    Exercise(id:'core_fr_6e_tn1',lessonId:'core_fr_6e_tenses',question:'Nous ___ au marché. (aller, présent)',options:['allons','allez','va'],correctIndex:0,explanation:'Avec nous, aller se conjugue allons.'),
    Exercise(id:'core_fr_6e_tn2',lessonId:'core_fr_6e_tenses',question:'« Elle ___ arrivée » : choisir l’auxiliaire.',options:['est','a','sont'],correctIndex:0,explanation:'Arriver se conjugue généralement avec être au passé composé.'),
    Exercise(id:'core_fr_6e_tn3',lessonId:'core_fr_6e_tenses',question:'Le passé composé se forme avec…',options:['Un auxiliaire et un participe passé','Un déterminant et un nom','Un adverbe seul'],correctIndex:0,explanation:'La construction du passé composé associe avoir ou être au participe passé.'),
  ]),
  AnnualSecondaryFrenchUnit(level:SchoolLevel.sixieme,code:'6e',unitOrder:3,title:'Accords dans le groupe nominal',lessonId:'core_fr_6e_noun_agreement',lessonTitle:'Accorder déterminant, nom et adjectif',summary:'Respecter le genre et le nombre dans le groupe nominal.',content:'Le déterminant, le nom et l’adjectif s’accordent en genre et en nombre. Un nom masculin singulier peut devenir féminin ou pluriel ; l’adjectif prend les marques correspondantes. Exemple : un petit garçon, une petite fille, des petites filles. Pour vérifier, repère le nom noyau et contrôle chaque mot qui dépend de lui.',keyPoints:['Repérer le nom noyau','Accord en genre : masculin/féminin','Accord en nombre : singulier/pluriel'],exercises:[
    Exercise(id:'core_fr_6e_na1',lessonId:'core_fr_6e_noun_agreement',question:'Choisir le groupe nominal correct.',options:['Des petites maisons','Des petit maison','Une petits maisons'],correctIndex:0,explanation:'Maisons est féminin pluriel : déterminant et adjectif s’accordent.'),
    Exercise(id:'core_fr_6e_na2',lessonId:'core_fr_6e_noun_agreement',question:'Le féminin de « heureux » est…',options:['heureuse','heureuxse','heureux'],correctIndex:0,explanation:'Heureux devient heureuse au féminin.'),
    Exercise(id:'core_fr_6e_na3',lessonId:'core_fr_6e_noun_agreement',question:'Dans « les élèves sérieux », « sérieux » est au…',options:['Masculin pluriel','Féminin singulier','Masculin singulier'],correctIndex:0,explanation:'Le nom élèves est ici au masculin pluriel dans le groupe proposé.'),
  ]),
  AnnualSecondaryFrenchUnit(level:SchoolLevel.sixieme,code:'6e',unitOrder:4,title:'Comprendre un récit',lessonId:'core_fr_6e_reading',lessonTitle:'Repérer personnages, cadre et étapes du récit',summary:'Lire un récit et relever les informations essentielles.',content:'Pour comprendre un récit, repère les personnages, le lieu, le moment et les événements. Le début présente souvent la situation initiale ; un événement déclenche l’action ; les péripéties racontent les étapes ; le dénouement résout le problème. Appuie tes réponses sur des indices du texte et distingue ce qui est dit de ce que tu déduis.',keyPoints:['Personnages, lieu et temps','Situation initiale, événement, péripéties, dénouement','Justifier une réponse par un indice du texte'],exercises:[
    Exercise(id:'core_fr_6e_rd1',lessonId:'core_fr_6e_reading',question:'La situation initiale présente généralement…',options:['Les personnages et le cadre','La solution finale seulement','La morale uniquement'],correctIndex:0,explanation:'Elle installe les personnages, le lieu et le moment.'),
    Exercise(id:'core_fr_6e_rd2',lessonId:'core_fr_6e_reading',question:'Pour justifier une réponse de lecture, il faut…',options:['Citer ou relever un indice du texte','Inventer un détail','Ignorer le texte'],correctIndex:0,explanation:'Une justification s’appuie sur une information du texte.'),
    Exercise(id:'core_fr_6e_rd3',lessonId:'core_fr_6e_reading',question:'Le dénouement correspond…',options:['À la résolution de l’action','Au titre uniquement','À la liste des personnages'],correctIndex:0,explanation:'Le dénouement résout le problème principal du récit.'),
  ]),
  AnnualSecondaryFrenchUnit(level:SchoolLevel.sixieme,code:'6e',unitOrder:5,title:'Décrire et rédiger un paragraphe',lessonId:'core_fr_6e_description',lessonTitle:'Organiser une description claire',summary:'Décrire une personne, un lieu ou un objet avec des détails ordonnés.',content:'Une description donne au lecteur des informations précises. Organise les détails dans un ordre logique : du général au particulier, de gauche à droite ou du premier plan à l’arrière-plan. Utilise des adjectifs, des groupes nominaux et des comparaisons simples. Un paragraphe comporte des phrases liées autour d’une idée et une ponctuation correcte.',keyPoints:['Choisir un ordre de description','Utiliser un vocabulaire précis','Relier les phrases autour d’une idée'],exercises:[
    Exercise(id:'core_fr_6e_ds1',lessonId:'core_fr_6e_description',question:'Une description efficace doit…',options:['Suivre un ordre logique','Accumuler des mots sans ordre','Éviter tout détail'],correctIndex:0,explanation:'Un ordre logique aide le lecteur à visualiser ce qui est décrit.'),
    Exercise(id:'core_fr_6e_ds2',lessonId:'core_fr_6e_description',question:'Quel mot est un adjectif descriptif ?',options:['lumineux','courir','hier'],correctIndex:0,explanation:'Lumineux décrit une caractéristique.'),
    Exercise(id:'core_fr_6e_ds3',lessonId:'core_fr_6e_description',question:'Un paragraphe développe…',options:['Une idée principale','Des idées sans lien','Seulement une ponctuation'],correctIndex:0,explanation:'Les phrases d’un paragraphe doivent se rapporter à une idée principale.'),
  ]),
];

final annualSecondaryFrenchChapters = annualSecondaryFrenchUnits.map((unit) => Chapter(
  id:unit.chapterId,subjectId:unit.subjectId,title:'Unité ${unit.unitOrder} — ${unit.title}',
  order:unit.unitOrder,term:unit.unitOrder,totalLessons:1,
)).toList();

final annualSecondaryFrenchLessons = annualSecondaryFrenchUnits.map((unit) => Lesson(
  id:unit.lessonId,chapterId:unit.chapterId,title:unit.lessonTitle,
  summary:unit.summary,content:unit.content,keyPoints:unit.keyPoints,durationMinutes:25,
)).toList();

final annualSecondaryFrenchExercises = annualSecondaryFrenchUnits.expand((unit)=>unit.exercises).toList();
